// necklaces.cpp -- distinct abelian squares in binary circular words, one word per necklace.
//
// Words are strings over {a, b}. The necklaces of length n are generated by the
// Fredricksen-Kessler-Maiorana algorithm; D(w) depends only on the necklace, since a
// rotation of w has the same circular factors. For every n <= NMAX the program checks
//   (1) min D = floor((n-1)/2) over all necklaces,
//   (2) the necklaces attaining it are exactly those of
//         n odd:  a^n, b^n, a^(n-1) b, b^(n-1) a;
//         n even: a^k b^(n-k), k odd (this includes the complements), and (ab)^(n/2) when
//                 n = 2 mod 4,
//       compared as sets of least rotations;
//   (3) Conjecture 0.6 (a) holds and the uniqueness in (b) fails exactly for n = 2 mod 4, n >= 6.
// Abelian squares are recognized with prefix sums of the number of a's on the doubled word.
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <set>
#include <string>
#include <vector>

static const int NMAX = 28;

static std::string least_rotation(const std::string& w) {
  std::string best = w;
  for (size_t r = 1; r < w.size(); r++) {
    std::string s = w.substr(r) + w.substr(0, r);
    if (s < best) best = s;
  }
  return best;
}

static int distinct_abelian_squares(const std::string& w) {
  const int n = (int)w.size();
  std::string ww = w + w;
  std::vector<int> pre(2 * n + 1, 0);  // pre[i] = number of a's in ww[0, i)
  for (int i = 0; i < 2 * n; i++) pre[i + 1] = pre[i] + (ww[i] == 'a');
  std::vector<uint64_t> keys;
  for (int m = 1; 2 * m <= n; m++)
    for (int i = 0; i < n; i++) {
      if (pre[i + m] - pre[i] != pre[i + 2 * m] - pre[i + m]) continue;
      uint64_t key = 1;  // leading 1, then the 2m letters
      for (int t = 0; t < 2 * m; t++) key = (key << 1) | (ww[i + t] == 'a');
      keys.push_back(key);
    }
  std::sort(keys.begin(), keys.end());
  return (int)(std::unique(keys.begin(), keys.end()) - keys.begin());
}

// Fredricksen-Kessler-Maiorana: visit every binary necklace of length n
template <class F>
static void necklaces(int n, F visit) {
  std::vector<int> a(n + 1, 0);
  std::string w(n, 'b');
  int t = 1, p = 1;
  // iterative form of the recursive generator
  struct Frame { int t, p, j; };
  std::vector<Frame> st;
  st.push_back({1, 1, -1});
  while (!st.empty()) {
    Frame& f = st.back();
    t = f.t; p = f.p;
    if (t > n) {
      if (n % p == 0) {
        for (int i = 1; i <= n; i++) w[i - 1] = a[i] ? 'a' : 'b';
        visit(w);
      }
      st.pop_back();
      continue;
    }
    if (f.j == -1) {
      f.j = a[t - p];
      a[t] = a[t - p];
      st.push_back({t + 1, p, -1});
      continue;
    }
    if (f.j < 1) {
      f.j++;
      a[t] = f.j;
      st.push_back({t + 1, t, -1});
      continue;
    }
    st.pop_back();
  }
}

static std::string block(int k, int n, char x, char y) { return std::string(k, x) + std::string(n - k, y); }

int main() {
  bool ok_all = true;
  for (int n = 1; n <= NMAX; n++) {
    std::set<std::string> family;
    if (n % 2 == 1) {
      family.insert(least_rotation(block(n, n, 'a', 'b')));
      family.insert(least_rotation(block(n, n, 'b', 'a')));
      family.insert(least_rotation(block(n - 1, n, 'a', 'b')));
      family.insert(least_rotation(block(n - 1, n, 'b', 'a')));
    } else {
      for (int k = 1; k < n; k += 2) {
        family.insert(least_rotation(block(k, n, 'a', 'b')));
        family.insert(least_rotation(block(k, n, 'b', 'a')));
      }
      if (n % 4 == 2) {
        std::string alt;
        for (int i = 0; i < n; i++) alt += (i % 2 == 0) ? 'a' : 'b';
        family.insert(least_rotation(alt));
      }
    }
    int target = (n - 1) / 2, minD = 1 << 30;
    long count = 0;
    std::set<std::string> attained;
    necklaces(n, [&](const std::string& w) {
      count++;
      int d = distinct_abelian_squares(w);
      if (d < minD) { minD = d; attained.clear(); }
      if (d == minD) attained.insert(least_rotation(w));
    });
    // Simpson's statement for comparison
    std::set<std::string> simpson;
    if (n % 2 == 1) {
      simpson = family;
    } else {
      for (int k = 1; k < n; k += 2) {
        simpson.insert(least_rotation(block(k, n, 'a', 'b')));
        simpson.insert(least_rotation(block(k, n, 'b', 'a')));
      }
    }
    bool ok = (minD == target) && attained == family;
    bool simpson_holds = (minD == target) && attained == simpson;
    bool expect_simpson = !(n % 4 == 2 && n >= 6);
    ok = ok && (simpson_holds == expect_simpson);
    std::printf("n=%2d  necklaces=%8ld  min D=%2d  extremal necklaces=%3zu  family=%3zu  "
                "Simpson's list %s  %s\n",
                n, count, minD, attained.size(), family.size(),
                simpson_holds ? "complete" : "INCOMPLETE", ok ? "ok" : "FAIL");
    if (!ok) ok_all = false;
  }
  std::puts(ok_all ? "ALL OK" : "SOME CHECKS FAILED");
  return ok_all ? 0 : 1;
}
